class Budget:
    started_s: float
    clock: Callable[[], float] = time.monotonic
    factory_attempts: int = 0
    integration_attempts: int = 0
    visitor_calls: int = 0
    acceleration_callbacks: int = 0
    spice_queries: int = 0
    kernel_reads: int = 0
    real_archive_reads: int = 0
    failed: bool = False
    previous_s: float | None = None

    def check(self) -> None:
        if self.failed:
            raise FixtureError("fixture already failed")
        try:
            now = _number(self.clock(), "monotonic clock")
            started = _number(self.started_s, "started_s")
            if now < started or (self.previous_s is not None and now < self.previous_s):
                raise FixtureError("monotonic clock moved backwards")
            self.previous_s = now
            if now - started >= 45.0:
                raise FixtureError("producer45s deadline exhausted")
        except (FixtureError, OSError, ValueError, TypeError, RuntimeError):
            self.failed = True
            raise

    def _charge(self, name: str, maximum: int) -> None:
        self.check()
        count = getattr(self, name)
        if type(count) is not int or not 0 <= count < maximum:
            self.failed = True
            raise FixtureError(f"{name} cap{maximum}")
        setattr(self, name, count + 1)

    def charge_factory(self, simulate: bool) -> None:
        if type(simulate) is not bool:
            self.failed = True
            raise FixtureError("simulate: boolean required")
        self._charge("factory_attempts", 3)
        if simulate:
            self._charge("integration_attempts", 2)

    def charge_visitor(self) -> None:
        self._charge("visitor_calls", 8)

    def charge_acceleration(self) -> None:
        self._charge("acceleration_callbacks", 100000)

    def snapshot(self) -> dict[str, object]:
        return {name: getattr(self, name) for name in (
            "factory_attempts", "integration_attempts", "visitor_calls",
            "acceleration_callbacks", "spice_queries", "kernel_reads", "real_archive_reads",
        )} | {"optimizer_entries": 0, "native_reported_function_evaluations": []}

def _counts(budget: Budget, factory: int, visitor: int) -> dict[str, object]:
    """Enforce the small scope, beyond the reused Budget's wider old maxima."""
    budget.check()
    counts = budget.snapshot()
    fixed = {"factory_attempts": factory, "integration_attempts": 0,
             "visitor_calls": visitor, "spice_queries": 0, "kernel_reads": 0,
             "real_archive_reads": 0, "optimizer_entries": 0}
    if type(counts) is not dict or set(counts) != set(fixed) | {
            "acceleration_callbacks", "native_reported_function_evaluations"}:
        raise RunError("setup counts: fixed fields required")
    for field, value in fixed.items():
        if type(counts[field]) is not int or counts[field] != value:
            raise RunError("setup counts: strict1/0/1 scope: " + field)
    callbacks = counts["acceleration_callbacks"]
    if type(callbacks) is not int or not 0 <= callbacks <= 100000:
        raise RunError("setup counts: acceleration callback cap100000")
    if type(counts["native_reported_function_evaluations"]) is not list or counts[
            "native_reported_function_evaluations"]:
        raise RunError("setup counts: no integrated function report")
    return counts
